//! Shared helpers for the log-io fuzz targets: an `Arbitrary` record
//! description, invariant checks, and a reference logfmt parser.

use arbitrary::Arbitrary;
use log_io::format::Format;
use log_io::{Field, Level, Metadata, Record, Value};

/// A record with owned data, generated by the fuzzer.
#[derive(Arbitrary, Debug)]
pub struct FuzzRecord {
    level: u8,
    pub target: String,
    pub message: String,
    timestamp: Option<u128>,
    location: Option<(String, u32)>,
    fields: Vec<(String, FuzzValue)>,
    context: Vec<(String, FuzzValue)>,
}

/// Every `Value` variant, with owned data.
#[derive(Arbitrary, Debug)]
pub enum FuzzValue {
    Null,
    Bool(bool),
    I64(i64),
    U64(u64),
    I128(i128),
    U128(u128),
    F64(f64),
    Str(String),
    Char(char),
    Bytes(Vec<u8>),
    Display(String),
    Debug(String),
}

impl FuzzValue {
    pub fn as_value(&self) -> Value<'_> {
        match self {
            Self::Null => Value::Null,
            Self::Bool(b) => Value::Bool(*b),
            Self::I64(n) => Value::I64(*n),
            Self::U64(n) => Value::U64(*n),
            Self::I128(n) => Value::I128(*n),
            Self::U128(n) => Value::U128(*n),
            Self::F64(n) => Value::F64(*n),
            Self::Str(s) => Value::Str(s),
            Self::Char(c) => Value::Char(*c),
            Self::Bytes(b) => Value::Bytes(b),
            Self::Display(s) => Value::Display(s),
            Self::Debug(s) => Value::Debug(s),
        }
    }
}

impl FuzzRecord {
    pub fn level(&self) -> Level {
        Level::ALL[usize::from(self.level) % Level::ALL.len()]
    }

    /// Build a borrowed [`Record`] and pass it to `f`.
    pub fn with_record<R>(&self, f: impl FnOnce(&Record<'_>) -> R) -> R {
        let fields: Vec<Field<'_>> = self
            .fields
            .iter()
            .map(|(k, v)| Field::new(k, v.as_value()))
            .collect();
        let context: Vec<Field<'_>> = self
            .context
            .iter()
            .map(|(k, v)| Field::new(k, v.as_value()))
            .collect();
        let mut meta = Metadata::new(self.level(), &self.target);
        if let Some(ts) = self.timestamp {
            meta = meta.with_timestamp(ts);
        }
        if let Some((file, line)) = &self.location {
            meta = meta.with_location(file, *line);
        }
        f(&Record::with_context(meta, &self.message, &fields, &context))
    }

    pub fn fields(&self) -> impl Iterator<Item = (&str, &FuzzValue)> {
        self.fields.iter().map(|(k, v)| (k.as_str(), v))
    }
}

/// Render a record with both dispatch paths and check they agree.
pub fn render<F: Format>(format: &F, record: &Record<'_>) -> String {
    let mut fast = String::new();
    format.write_record_generic(record, &mut fast).unwrap();
    let mut dynamic = String::new();
    format.write_record(record, &mut dynamic).unwrap();
    assert_eq!(fast, dynamic, "static and dynamic dispatch disagree");
    fast
}

/// Characters no built-in format may emit raw.
pub fn is_forbidden(c: char) -> bool {
    c.is_control() || matches!(c, '\u{2028}'..='\u{202e}' | '\u{2066}'..='\u{2069}')
}

/// Assert one newline-terminated line with no forbidden characters.
pub fn assert_single_safe_line(out: &str) {
    assert!(out.ends_with('\n'), "missing newline: {out:?}");
    let body = &out[..out.len() - 1];
    assert!(!body.chars().any(is_forbidden), "unsafe character in {out:?}");
}

/// Strict parser for the logfmt dialect `LogfmtFormat` writes. Returns
/// `None` if the line is malformed.
pub fn parse_logfmt(line: &str) -> Option<Vec<(String, String)>> {
    let mut pairs = Vec::new();
    let mut chars = line.chars().peekable();
    loop {
        let mut key = String::new();
        loop {
            match chars.next()? {
                '=' => break,
                ' ' | '"' => return None,
                c => key.push(c),
            }
        }
        if key.is_empty() {
            return None;
        }
        let mut value = String::new();
        if chars.peek() == Some(&'"') {
            chars.next();
            loop {
                match chars.next()? {
                    '"' => break,
                    '\\' => match chars.next()? {
                        '"' => value.push('"'),
                        '\\' => value.push('\\'),
                        'n' => value.push('\n'),
                        'r' => value.push('\r'),
                        't' => value.push('\t'),
                        'b' => value.push('\u{8}'),
                        'f' => value.push('\u{c}'),
                        'u' => {
                            let hex: String = (0..4).filter_map(|_| chars.next()).collect();
                            value.push(char::from_u32(u32::from_str_radix(&hex, 16).ok()?)?);
                        }
                        _ => return None,
                    },
                    c => value.push(c),
                }
            }
        } else {
            while let Some(&c) = chars.peek() {
                if c == ' ' {
                    break;
                }
                if c == '"' || c == '=' {
                    return None;
                }
                value.push(c);
                chars.next();
            }
        }
        pairs.push((key, value));
        match chars.next() {
            None => return Some(pairs),
            Some(' ') => {}
            Some(_) => return None,
        }
    }
}
